const LF = String.fromCharCode(10);
const allItems = $input.all();
const body = (allItems[0] && allItems[0].json) ? allItems[0].json : {};
const results = Array.isArray(body.results) ? body.results : [];
const answer = body.answer || "";
let topic = "";
try { topic = $("Extract Topic").item.json.topic || ""; } catch (e) { topic = body.query || ""; }

const blocks = results.map(function (r, i) {
  const title = r.title || "Untitled source";
  const url = r.url || "";
  const content = (r.content || "").toString();
  return (i + 1) + ". " + title + LF + "URL: " + url + LF + "Excerpt: " + content;
});

const sourcesText = blocks.length ? blocks.join(LF + LF) : "No sources were returned.";
const sourceList = results.map(function (r) {
  return { title: r.title || "Untitled source", url: r.url || "" };
});

return [{ json: { topic: topic, answer: answer, sourcesText: sourcesText, sourceList: sourceList } }];

