const LF = String.fromCharCode(10);
const report = ($input.first().json.output || "").toString();
let topic = "Research Report";
try { topic = $("Extract Topic").item.json.topic || topic; } catch (e) {}

function esc(s) {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}
function inline(s) {
  let t = esc(s);
  t = t.replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g, '<a href="$2" target="_blank">$1</a>');
  t = t.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
  t = t.replace(/\*([^*]+)\*/g, "<em>$1</em>");
  return t;
}

const lines = report.split(/\r?\n/);
const parts = [];
let inList = false;
function closeList() { if (inList) { parts.push("</ul>"); inList = false; } }

for (let i = 0; i < lines.length; i++) {
  const raw = lines[i];
  const line = raw.trim();
  if (!line) { closeList(); continue; }
  const h = line.match(/^(#{1,6})\s+(.*)$/);
  if (h) {
    closeList();
    const level = h[1].length;
    parts.push("<h" + level + ">" + inline(h[2]) + "</h" + level + ">");
    continue;
  }
  const li = line.match(/^[-*]\s+(.*)$/);
  if (li) {
    if (!inList) { parts.push("<ul>"); inList = true; }
    parts.push("<li>" + inline(li[1]) + "</li>");
    continue;
  }
  closeList();
  parts.push("<p>" + inline(line) + "</p>");
}
closeList();

const styleParts = [
  "body{font-family:Segoe UI,Arial,sans-serif;line-height:1.6;color:#1a1a1a;background:#f4f6f8;margin:0;padding:40px;}",
  ".report{max-width:860px;margin:0 auto;background:#fff;padding:48px 56px;border-radius:10px;box-shadow:0 2px 12px rgba(0,0,0,0.08);}",
  "h1{font-size:30px;color:#0b3d91;border-bottom:3px solid #0b3d91;padding-bottom:12px;margin-top:0;}",
  "h2{font-size:21px;color:#0b3d91;margin-top:32px;border-left:4px solid #0b3d91;padding-left:12px;}",
  "h3{font-size:17px;color:#333;}",
  "p{margin:12px 0;}",
  "ul{margin:12px 0 12px 24px;}",
  "li{margin:6px 0;}",
  "a{color:#0b5cff;text-decoration:none;}",
  "a:hover{text-decoration:underline;}",
  ".footer{margin-top:40px;padding-top:16px;border-top:1px solid #e0e0e0;font-size:12px;color:#888;text-align:center;}",
];
const style = styleParts.join(LF);

const generatedOn = new Date().toISOString().slice(0, 10);
const html = [
  "<!DOCTYPE html>",
  '<html lang="en">',
  "<head>",
  '<meta charset="UTF-8">',
  '<meta name="viewport" content="width=device-width, initial-scale=1.0">',
  "<title>" + esc(topic) + " - Research Report</title>",
  "<style>" + style + "</style>",
  "</head>",
  "<body>",
  '<div class="report">',
  parts.join(LF),
  '<div class="footer">Generated by AI Research Agent on ' + generatedOn + "</div>",
  "</div>",
  "</body>",
  "</html>",
].join(LF);

return [{ json: { output: html, html: html, topic: topic } }];
